from abc import ABC
from itertools import cycle, islice
from typing import List, Optional, Union

from taf.rfrl.csv4all.resources.test_cases.csv4all_test import CSV4AllTest, test_logger, method_decorator


class CellOperationTest(CSV4AllTest, ABC):

    def __init__(self, nodes_details: List[dict], test_nodes_details: List[dict], iterations_per_node: int,
                 report: bool, calculate_kpi: Optional[bool] = True, kpi_targets: Optional[dict] = None,
                 use_dcap: Optional[bool] = False, qc_domain: Optional[str] = None, qc_id: Optional[str] = None,
                 qc_project: Optional[str] = None, customers_list: Optional[list] = None,
                 report_comment: Optional[str] = None, sw_build: Optional[str] = None, topology: Optional[str] = None,
                 rat: Optional[str] = None, stop_test_after_fail: bool = False,
                 l3_call_method: Optional[callable] = None, detailed_console_log: bool = True,
                 collect_passed_logs: int = 0):
        super().__init__(nodes_details, test_nodes_details, iterations_per_node, report,
                         calculate_kpi, kpi_targets, use_dcap, qc_domain, qc_id, qc_project, customers_list,
                         report_comment, sw_build, topology, stop_test_after_fail, l3_call_method,
                         detailed_console_log, collect_passed_logs)
        self.rat = rat

    def remove_nodes_without_specified_rat_from_test(self):

        for node in [node for node in self.test_nodes if not node.cells_per_rat.get(self.rat)]:
            test_logger(f"Node {node.node_alias} doesn't have any configured cells for rat {self.rat}, "
                        f"this node won't take part in test!", log_level="WARN")
            self.test_nodes.remove(node)

    @method_decorator()
    def get_cells_list_per_band(self, node):
        cells_per_band = {band: [cell
                                 for cell, cell_details in node.cells_per_rat[self.rat].items() if
                                 cell_details.get("band") == band and not cell_details.get("IoT Cell")]
                          for band in
                          {cell_details.get("band") for cell, cell_details in node.cells_per_rat[self.rat].items()
                          if not cell_details.get("IoT Cell")}}
        test_logger(f"Cells which will be used during test: {cells_per_band}")
        return cells_per_band

    @method_decorator()
    def set_list_of_bands_for_test(self):
        for node in self.test_nodes:
            if not hasattr(node, "bands_for_test"):
                bands_list = [band for band in self.get_cells_list_per_band(node).keys()]
            else:
                bands_list = node.bands_for_test
            node.bands_for_test = iter(islice(cycle(bands_list), 2 * self.iterations_per_node))
            test_logger(f"Bands which will be used during test for node {node.node_alias} : {bands_list}")

    def test_setup(self):
        super().test_setup()
        self.remove_nodes_without_specified_rat_from_test()
        self.set_list_of_bands_for_test()

    @method_decorator()
    def run_kpi_calculation(self, node):
        if node.btsverify.cells_verifier.energy_saving_cells:
            test_logger("Cells detected in energy saving state. Calculating KPI for current iteration will be disabled.",
                        "WARN")
            test_logger(f"EnergySaving Cells: {node.btsverify.cells_verifier.energy_saving_cells}", "DEBUG")
            node.btsverify.cells_verifier.energy_saving_cells.clear()
        else:
            super().run_kpi_calculation(node)

    @method_decorator()
    def remove_cells_from_energy_saving_cells(self, node, cells: Union[list, str]):
        if isinstance(cells, str):
            cells = [cells]
        test_logger(f"energy saving cells before: {node.btsverify.cells_verifier.energy_saving_cells}", "DEBUG")
        node.btsverify.cells_verifier.energy_saving_cells = {cell for cell in
                                                             node.btsverify.cells_verifier.energy_saving_cells
                                                             if cell not in cells}
        test_logger(f"energy saving cells after: {node.btsverify.cells_verifier.energy_saving_cells}", "DEBUG")
